import React, { useState, useEffect, useCallback } from 'react';

const API = 'http://localhost:5000/api';
const EMOJIS = ['📋','🎮','⏰','📅','✅','❌','🔍','🔄'];

export default function AdminRentals() {
  const [rentals, setRentals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [msg, setMsg] = useState({ type: '', text: '' });

  const loadRentals = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API}/rentals`);
      const data = await res.json();
      setRentals(Array.isArray(data) ? data : data.rentals || []);
    } catch (error) {
      console.error('Error loading rentals:', error);
      setRentals([]);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadRentals();
  }, [loadRentals]);

  const handleReturnRental = async (rentalId) => {
    if (!window.confirm('Return this rental?')) return;

    try {
      const res = await fetch(`${API}/rentals/return/${rentalId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' }
      });

      if (res.ok) {
        setMsg({ type: 'success', text: 'Rental returned' });
        loadRentals();
      } else {
        const data = await res.json();
        setMsg({ type: 'error', text: data.message || 'Failed to return' });
      }
    } catch (error) {
      setMsg({ type: 'error', text: 'Error returning rental' });
    }
  };

  const handleDeleteRental = async (rentalId) => {
    if (!window.confirm('Delete this rental?')) return;

    try {
      const res = await fetch(`${API}/rentals/${rentalId}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setMsg({ type: 'success', text: 'Rental deleted' });
        loadRentals();
      } else {
        const data = await res.json();
        setMsg({ type: 'error', text: data.message || 'Failed to delete' });
      }
    } catch (error) {
      setMsg({ type: 'error', text: 'Error deleting rental' });
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleDateString();
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'ACTIVE': return '#FFA500';
      case 'ON TIME': return '#28A745';
      case 'LATE': return '#DC3545';
      default: return '#6C757D';
    }
  };

  const filteredRentals = rentals.filter(rental => {
    const matchesSearch = !search || 
      rental.UserName?.toLowerCase().includes(search.toLowerCase()) ||
      rental.GameTitle?.toLowerCase().includes(search.toLowerCase()) ||
      rental.CopyID?.toString().includes(search);

    const matchesFilter = filter === 'all' || 
      (filter === 'active' && rental.RentalStatus === 'ACTIVE') ||
      (filter === 'returned' && rental.RentalStatus !== 'ACTIVE') ||
      (filter === 'late' && rental.RentalStatus === 'LATE');

    return matchesSearch && matchesFilter;
  });

  const activeRentals = rentals.filter(r => r.RentalStatus === 'ACTIVE').length;
  const lateRentals = rentals.filter(r => r.RentalStatus === 'LATE').length;

  return (
    <div>
      <div className="page-header">
        <div>
          <div className="page-title">📋 RENTAL MANAGEMENT</div>
          <div className="page-sub">{rentals.length} rentals in system</div>
        </div>
        <div className="page-stats">
          <div className="stat">
            <div className="stat-number">{activeRentals}</div>
            <div className="stat-label">Active</div>
          </div>
          <div className="stat">
            <div className="stat-number" style={{ color: '#DC3545' }}>{lateRentals}</div>
            <div className="stat-label">Late</div>
          </div>
        </div>
      </div>

      {msg.text && (
        <div className={`alert alert-${msg.type}`}>
          {msg.text}
        </div>
      )}

      <div className="controls">
        <div className="search-bar">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            placeholder="Search rentals..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <select value={filter} onChange={(e) => setFilter(e.target.value)}>
          <option value="all">All Rentals</option>
          <option value="active">Active</option>
          <option value="returned">Returned</option>
          <option value="late">Late</option>
        </select>
        <button onClick={loadRentals}>🔄 Refresh</button>
      </div>

      {loading ? (
        <div className="loading">Loading rentals...</div>
      ) : filteredRentals.length === 0 ? (
        <div className="empty">
          <div className="empty-icon">📋</div>
          <p>No rentals found</p>
        </div>
      ) : (
        <div className="rentals-grid">
          {filteredRentals.map((rental) => (
            <div key={rental.RentalID} className="rental-card">
              <div className="rental-header">
                <div className="rental-id">#{rental.RentalID}</div>
                <div 
                  className="rental-status" 
                  style={{ backgroundColor: getStatusColor(rental.RentalStatus) }}
                >
                  {rental.RentalStatus}
                </div>
              </div>

              <div className="rental-user">
                <strong>{rental.UserName}</strong>
                {rental.UserEmail && <div className="user-email">{rental.UserEmail}</div>}
              </div>

              <div className="rental-game">
                <strong>{rental.GameTitle}</strong>
                <div className="game-details">
                  {rental.Platform} • {rental.Genre}
                </div>
              </div>

              <div className="rental-copy">
                <span className="copy-badge">Copy ID: {rental.CopyID}</span>
              </div>

              <div className="rental-dates">
                <div className="date-row">
                  <span>📅 Issued:</span>
                  <span>{formatDate(rental.DateIssued)}</span>
                </div>
                <div className="date-row">
                  <span>⏰ Due:</span>
                  <span style={{ 
                    color: new Date(rental.DateDue) < new Date() && rental.RentalStatus === 'ACTIVE' ? '#DC3545' : 'inherit' 
                  }}>
                    {formatDate(rental.DateDue)}
                  </span>
                </div>
                <div className="date-row">
                  <span>✅ Returned:</span>
                  <span>{rental.DateReturned ? formatDate(rental.DateReturned) : '-'}</span>
                </div>
              </div>

              {rental.DaysOverdue > 0 && (
                <div className="overdue-info">
                  <span style={{ color: '#DC3545', fontWeight: 'bold' }}>
                    ⚠️ {rental.DaysOverdue} days overdue
                  </span>
                </div>
              )}

              <div className="rental-actions">
                {rental.RentalStatus === 'ACTIVE' && (
                  <button 
                    onClick={() => handleReturnRental(rental.RentalID)}
                    className="btn-return"
                  >
                    Return
                  </button>
                )}
                <button 
                  onClick={() => handleDeleteRental(rental.RentalID)}
                  className="btn-delete"
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
